mapper.select:
select WTPD.TRADE_ID tradeId, #{VALID_STATUS_01} validStatus, WTPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, WTPD.TRADE_DATE tradeDate, WTPDO.IRS_TYPE irsType, WTPD.VDATE vdate, WTPD.MDATE mdate, WTPDO.TERM term, WTPD.CCY ccy, WTPD.PRIN_AMT/10000 prin, WTPDO.RATE yield, WTPDO.PAY_CYCLE_R fixPayCycle, WTPDO.FIRST_PAY_DATE_R firstPayDateR, WTPDO.INT_RATE_ID intType, WTPDO.SPREAD_RATE_F spreadRate, WTPDO.PAY_CYCLE_F floatPayCycle, WTPDO.FIRST_PAY_DATE_F firstPayDateF, party.counter_name counterId, WTPD.TRADER trader, WTPD.REMARK remark, WTPD.WORKFLOW_ID workflowId, WTPD.WORKFLOW_STATUS workflowStatus, WTPD.FINPROD_TYPE2 finprodType2, WTPD.FINPROD_ID finprodId from WFL_TRD_PRODUCT_DEAL WTPD left join WFL_TRD_PRODUCT_DEAL_ADD WTPDA on WTPD.TRADE_ID = WTPDA.TRADE_ID left join PTL_PORTFOLIO PP on WTPDA.PORTFOLIO_ID = PP.PORTFOLIO_ID left join WFL_TRD_PRODUCT_DEAL_OTH WTPDO on WTPD.TRADE_ID = WTPDO.TRADE_ID left join mst_counter_party party on WTPD.COUNTER_ID=party.counter_id where PP.INVEST_YESORNO='Y' AND WTPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F14} AND WTPD.PS = #{PS_T01}
AND (PP.PORTFOLIO_ID IN #{item}
OR PP.PARENT_PORTFOLIO_ID IN
#{item} )
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND WTPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND WTPDO.IRS_TYPE = #{irsType}
AND WTPDO.INT_RATE_ID = #{intType}
AND WTPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND WTPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and WTPD.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select TPD.TRADE_ID tradeId, #{VALID_STATUS_02} validStatus, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, TPD.TRADE_DATE tradeDate, FTP.IRS_TYPE irsType, TPD.VDATE vdate, TPD.MDATE mdate, FTP.TERM term, TPD.CCY ccy, TPD.PRIN_AMT/10000 prin, FCCR_R.Yield*100 yield, FCPR_R.PAY_CYCLE fixPayCycle, FCPR_R.FIRST_PAY_DATE firstPayDateR, FRI_F.BENCHMARK_ID intType, FRI_F.SPREAD_RATE spreadRate, FCPR_F.PAY_CYCLE floatPayCycle, FCPR_F.FIRST_PAY_DATE firstPayDateF, party.counter_name counterId, TPD.TRADER trader, TPD.REMARK remark, NULL workflowId, NULL workflowStatus, TPD.FINPROD_TYPE2 finprodType2, TPD.FINPROD_ID finprodId from TRD_PRODUCT_DEAL TPD left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID left join PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = TPD.FINPROD_ID and FTP.BRANCH = #{BRANCH_0} left join FIN_RATE_INFO FRI_R on FRI_R.FINPROD_ID = TPD.FINPROD_ID and FRI_R.BRANCH = #{BRANCH_0} and FRI_R.INT_TYPE = #{INT_TYPE_01} and FRI_R.EFF_DATE = FTP.VDATE left join FIN_RATE_INFO FRI_F on FRI_F.FINPROD_ID = TPD.FINPROD_ID and FRI_F.BRANCH = #{BRANCH_0} and FRI_F.INT_TYPE = #{INT_TYPE_02} and FRI_F.EFF_DATE = FTP.VDATE left join FIN_CASH_PAY_RULE FCPR_R on FRI_R.CASH_ID = FCPR_R.CASH_ID and FCPR_R.EFF_DATE = FTP.VDATE left join FIN_CASH_PAY_RULE FCPR_F on FRI_F.CASH_ID = FCPR_F.CASH_ID and FCPR_F.EFF_DATE = FTP.VDATE left join FIN_CASH_CALC_RULE FCCR_R on FRI_R.CASH_ID = FCCR_R.CASH_ID and FCCR_R.IS_INITIAL = #{YES_NO_YES} left join mst_counter_party party on TPD.COUNTER_ID=party.counter_id where PP.INVEST_YESORNO='Y' AND TPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F14} AND TPD.PS = #{PS_T01}
AND (PP.PORTFOLIO_ID IN #{item}
OR PP. PARENT_PORTFOLIO_ID IN
#{item} )
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND TPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND FTP.IRS_TYPE = #{irsType}
AND FRI_F.BENCHMARK_ID = #{intType}
AND TPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND TPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and (TPD.IS_CANCEL is null or TPD.IS_CANCEL = #{YES_NO_NO}) and TPD.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL select TPD.TRADE_ID tradeId, #{VALID_STATUS_03} validStatus, TPDA.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, TPD.TRADE_DATE tradeDate, FTP.IRS_TYPE irsType, TPD.VDATE vdate, TPD.MDATE mdate, FTP.TERM term, TPD.CCY ccy, TPD.PRIN_AMT/10000 prin, FCCR_R.Yield*100 yield, FCPR_R.PAY_CYCLE fixPayCycle, FCPR_R.FIRST_PAY_DATE firstPayDateR, FRI_F.BENCHMARK_ID intType, FRI_F.SPREAD_RATE spreadRate, FCPR_F.PAY_CYCLE floatPayCycle, FCPR_F.FIRST_PAY_DATE firstPayDateF, party.counter_name counterId, TPD.TRADER trader, TPD.REMARK remark, NULL workflowId, NULL workflowStatus, TPD.FINPROD_TYPE2 finprodType2, TPD.FINPROD_ID finprodId from TRD_PRODUCT_DEAL TPD left join TRD_PRODUCT_DEAL_ADD TPDA on TPD.TRADE_ID = TPDA.TRADE_ID left join PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO left join PTL_PORTFOLIO PP on PP.PORTFOLIO_ID = PT.PORTFOLIO_ID left join FIN_TRADE_PRODUCT FTP on FTP.FINPROD_ID = TPD.FINPROD_ID and FTP.BRANCH = #{BRANCH_0} left join FIN_RATE_INFO FRI_R on FRI_R.FINPROD_ID = TPD.FINPROD_ID and FRI_R.BRANCH = #{BRANCH_0} and FRI_R.INT_TYPE = #{INT_TYPE_01} and FRI_R.EFF_DATE = FTP.VDATE left join FIN_RATE_INFO FRI_F on FRI_F.FINPROD_ID = TPD.FINPROD_ID and FRI_F.BRANCH = #{BRANCH_0} and FRI_F.INT_TYPE = #{INT_TYPE_02} and FRI_F.EFF_DATE = FTP.VDATE left join FIN_CASH_PAY_RULE FCPR_R on FRI_R.CASH_ID = FCPR_R.CASH_ID and FCPR_R.EFF_DATE = FTP.VDATE left join FIN_CASH_PAY_RULE FCPR_F on FRI_F.CASH_ID = FCPR_F.CASH_ID and FCPR_F.EFF_DATE = FTP.VDATE left join FIN_CASH_CALC_RULE FCCR_R on FRI_R.CASH_ID = FCCR_R.CASH_ID and FCCR_R.IS_INITIAL = #{YES_NO_YES} left join mst_counter_party party on TPD.COUNTER_ID=party.counter_id where PP.INVEST_YESORNO='Y' AND TPD.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F14} AND TPD.PS = #{PS_T01}
AND (PP.PORTFOLIO_ID IN #{item}
OR PP. PARENT_PORTFOLIO_ID IN
#{item} )
and (PP.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR PP.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND TPDA.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND FTP.IRS_TYPE = #{irsType}
AND FRI_F.BENCHMARK_ID = #{intType}
AND TPD.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND TPD.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and TPD.IS_CANCEL = #{YES_NO_YES} and TPD.TRADE_STATUS = #{TRADE_STATUS_01}
ORDER BY tradeDate DESC, tradeId DESC
